import numpy as np

def generate_entries(features, signal_params):
    n = features.market.size
    volume_lookback = signal_params['volume_lookback']
    relative_volume_multiplier = signal_params['relative_volume_multiplier']
    body_max_fraction = signal_params['body_max_fraction']
    lower_shadow_min_fraction = signal_params['lower_shadow_min_fraction']
    lower_to_upper_shadow_multiplier = signal_params['lower_to_upper_shadow_multiplier']
    close_position_min_fraction = signal_params['close_position_min_fraction']
    opens = features.market.opens
    highs = features.market.highs
    lows = features.market.lows
    closes = features.market.closes
    volumes = features.market.volumes
    candle_range = highs - lows
    body = np.abs(closes - opens)
    upper_shadow = highs - np.maximum(opens, closes)
    lower_shadow = np.minimum(opens, closes) - lows
    average_volume = features.sma(volume_lookback, 'volumes')
    long_entries = ((candle_range > 0) & (volumes >= average_volume * relative_volume_multiplier) & (body <= candle_range * (body_max_fraction / 100.0)) & (lower_shadow >= candle_range * (lower_shadow_min_fraction / 100.0)) & (lower_shadow >= upper_shadow * lower_to_upper_shadow_multiplier) & (closes >= lows + candle_range * (close_position_min_fraction / 100.0))).astype(bool)
    short_entries = np.zeros(n, dtype=bool)
    return (long_entries, short_entries)

def i5_apply_trend_exit(features: object, long_entries: object, short_entries: object, signal_params: dict) -> tuple:
    return features.trend_exit(long_entries, short_entries)

def generate_signals(features, signal_params):
    import numpy as np
    long_entries, short_entries = generate_entries(features, signal_params)
    long_exits, short_exits = i5_apply_trend_exit(features, long_entries, short_entries, signal_params)
    no_distances = np.full(features.market.size, np.nan, dtype=np.float64)
    return (long_entries, long_exits, short_entries, short_exits, no_distances, no_distances)

